#include <iostream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    string s;
    cin >> s;

    int max_len = 0;

    for (int i = 0; i < n; ++i) {
        // Palíndromos de comprimento ímpar com centro em i
        int l = i, r = i;
        while (l >= 0 && r < n && s[l] == s[r]) {
            --l;
            ++r;
        }
        max_len = max(max_len, r - l - 1);

        // Palíndromos de comprimento par com centro entre i e i + 1
        l = i;
        r = i + 1;
        while (l >= 0 && r < n && s[l] == s[r]) {
            --l;
            ++r;
        }
        max_len = max(max_len, r - l - 1);
    }

    cout << max_len << "\n";

    return 0;
}
